```python
#!/usr/bin/env python3
"""
Fix common pyproject.toml errors - improved version.
"""

import re
import sys
from pathlib import Path

def read_pyproject(path: Path) -> str:
    if not path.exists():
        raise FileNotFoundError(f"{path} not found")
    return path.read_text()

def write_pyproject(path: Path, content: str):
    backup = path.with_suffix(".toml.backup")
    if not backup.exists():
        path.rename(backup)
        print(f"Backup: {backup}")
    path.write_text(content)
    print(f"Updated: {path}")

def fix_all(content: str) -> str:
    """Apply all fixes in correct order."""
    fixes = [
        fix_missing_version,
        fix_package_data_section,
        fix_underscore_in_section_name,
        fix_include_package_data,
    ]

    result = content
    for fix_func in fixes:
        result = fix_func(result)

    return result

def fix_missing_version(content: str) -> str:
    lines = content.split('\n')
    result = []
    in_project = False
    has_version = False

    for i, line in enumerate(lines):
        if line.strip() == "[project]":
            in_project = True
            result.append(line)
            continue

        if in_project and line.strip().startswith("["):
            in_project = False

        if in_project and re.match(r'^\s*version\s*=', line):
            has_version = True

        result.append(line)

    # Add version if missing
    if not has_version:
        for i in range(len(result)):
            if result[i].strip() == "[project]":
                # Add after [project] or after name
                for j in range(i+1, len(result)):
                    if re.match(r'^\s*name\s*=', result[j]):
                        indent = len(result[j]) - len(result[j].lstrip())
                        result.insert(j+1, " " * indent + 'version = "1.0.0"  # Added')
                        break
                else:
                    result.insert(i+1, 'version = "1.0.0"  # Added')
                break

    return '\n'.join(result)

def fix_package_data_section(content: str) -> str:
    """Move package_data from [tool.setuptools] to [tool.setuptools.package-data]"""
    lines = content.split('\n')
    result = []
    i = 0

    while i < len(lines):
        line = lines[i]

        # Handle package_data = ... inside [tool.setuptools]
        if line.strip() == "[tool.setuptools]":
            result.append(line)
            i += 1

            package_data_lines = []
            while i < len(lines) and not lines[i].strip().startswith("["):
                current = lines[i]
                if re.match(r'^\s*package_data\s*=', current):
                    # Extract value
                    match = re.search(r'package_data\s*=\s*(.+)', current)
                    if match:
                        value = match.group(1)
                        # Store to add later
                        package_data_lines.append(value)
                    # Skip this line (won't be added to result)
                else:
                    result.append(current)
                i += 1

            # Add package-data section after setuptools
            if package_data_lines:
                result.append("")
                result.append("[tool.setuptools.package-data]")
                for value in package_data_lines:
                    result.append(f"rendercv = {value}")

            continue

        result.append(line)
        i += 1

    return '\n'.join(result)

def fix_underscore_in_section_name(content: str) -> str:
    """Fix [tool.setuptools.package_data] -> [tool.setuptools.package-data]"""
    pattern = r'\[tool\.setuptools\.package_data\]'
    replacement = "[tool.setuptools.package-data]"

    if re.search(pattern, content):
        print("Fixed: [tool.setuptools.package_data] -> [tool.setuptools.package-data]")

    return re.sub(pattern, replacement, content)

def fix_include_package_data(content: str) -> str:
    """Ensure include-package-data = true exists in [tool.setuptools]"""
    lines = content.split('\n')
    result = []
    i = 0

    while i < len(lines):
        line = lines[i]

        if line.strip() == "[tool.setuptools]":
            result.append(line)
            i += 1

            # Check if include-package-data exists
            has_include = False
            section_lines = []

            while i < len(lines) and not lines[i].strip().startswith("["):
                current = lines[i]
                if "include-package-data" in current:
                    has_include = True
                section_lines.append(current)
                i += 1

            # Add include-package-data if missing
            if not has_include and section_lines:
                result.append("include-package-data = true  # Added")

            result.extend(section_lines)
            continue

        result.append(line)
        i += 1

    return '\n'.join(result)

def main():
    if len(sys.argv) < 2:
        print("Usage: python fix_pyproject_v2.py <pyproject.toml>")
        sys.exit(1)

    path = Path(sys.argv[1])

    try:
        content = read_pyproject(path)
        original = content

        print(f"Fixing: {path}")
        print("=" * 60)

        fixed = fix_all(content)

        if fixed != original:
            write_pyproject(path, fixed)

            # Show changes
            print("\nChanges made:")
            print("-" * 60)
            orig_lines = original.split('\n')
            fixed_lines = fixed.split('\n')

            for j in range(max(len(orig_lines), len(fixed_lines))):
                orig = orig_lines[j] if j < len(orig_lines) else ""
                fix = fixed_lines[j] if j < len(fixed_lines) else ""

                if orig != fix:
                    if j > 0:
                        print(f"Line {j+1}:")
                        if orig: print(f"  - {orig}")
                        if fix: print(f"  + {fix}")

            print("\n" + "=" * 60)
            print("Next steps:")
            print("1. pip install -e . --force-reinstall")
            print("2. python -c \"import rendercv; import os; print(os.path.exists(os.path.join(os.path.dirname(rendercv.__file__), 'error_dictionary.yaml')))\"")
            print("3. python -m pytest tests/ -v")
        else:
            print("No changes needed - pyproject.toml looks good!")

    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

